17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Produces hexadecimal SHA-256 digests, the shared building block for the deterministic
25	 * identifiers derived from owner data (customer code, household id, identity key).
26	 */
27	public final class Sha256Hex {
28	
29	    private Sha256Hex() {
30	    }
31	
32	    /**
33	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest of
34	     *         {@code value}'s UTF-8 bytes.
35	     */
36	    public static String upperHexPrefix(String value, int length) {
37	        byte[] digest = sha256(value.getBytes(StandardCharsets.UTF_8));
38	        StringBuilder hex = new StringBuilder(digest.length * 2);
39	        for (byte b : digest) {
40	            hex.append(String.format("%02X", b));
41	        }
42	        return hex.substring(0, length);
43	    }
44	
45	    /**
46	     * @return the full 64-character lower-case hex SHA-256 digest of {@code value}'s UTF-8 bytes.
47	     */
48	    public static String lowerHex(String value) {
49	        byte[] digest = sha256(value.getBytes(StandardCharsets.UTF_8));
50	        StringBuilder hex = new StringBuilder(digest.length * 2);
51	        for (byte b : digest) {
52	            hex.append(String.format("%02x", b));
53	        }
54	        return hex.toString();
55	    }
56	
57	    private static byte[] sha256(byte[] bytes) {
58	        try {
59	            return MessageDigest.getInstance("SHA-256").digest(bytes);
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 not available", ex);
63	        }
64	    }
65	}
