16	package org.springframework.samples.petclinic.rest;
17	
18	import java.time.LocalDate;
19	import java.util.Collection;
20	import java.util.HashSet;
21	import java.util.Set;
22	
23	import org.springframework.samples.petclinic.util.FiscalYearResolver;
24	import org.springframework.samples.petclinic.util.LocalityResolver;
25	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
26	import org.springframework.samples.petclinic.util.Sha256Hex;
27	import org.springframework.stereotype.Component;
28	
29	/**
30	 * Builds an owner's member id, formatted {@code '<REGION><FY><HASH8><CHK>'}: the region code
31	 * derived from the postcode, the 2-digit fiscal year of the (business-day-adjusted) registration
32	 * date, the first 8 upper-case hex characters of SHA-256 over the normalized telephone concatenated
33	 * with the last name, and a single Luhn check digit computed over the digits of the preceding
34	 * {@code <REGION><FY><HASH8>} body, e.g. {@code 'NSW273F2A9C1E4'}.
35	 */
36	@Component
37	public class MemberIdGenerator {
38	
39	    /** Separator introducing the numeric suffix a collision appends to an otherwise-taken id. */
40	    private static final char SEPARATOR = '-';
41	
42	    /** Number of hex characters taken from the SHA-256 digest for the hash segment. */
43	    private static final int HASH_LENGTH = 8;
44	
45	    /** Number of digits in the fiscal-year segment. */
46	    private static final int FISCAL_YEAR_LENGTH = 2;
47	
48	    /** Number of characters in the trailing check-digit segment. */
49	    private static final int CHECK_LENGTH = 1;
50	
51	    /** Combined length of the fixed trailing segments {@code <FY><HASH8><CHK>} after the region. */
52	    private static final int TRAILING_LENGTH = FISCAL_YEAR_LENGTH + HASH_LENGTH + CHECK_LENGTH;
53	
54	    /**
55	     * Generate the member id for a new owner.
56	     *
57	     * @param region           the region code derived from the owner's postcode; forms the prefix
58	     * @param registrationDate the owner's (business-day-adjusted) registration date; its fiscal
59	     *                         year forms the {@code FY} segment
60	     * @param telephone        the owner's normalized telephone; hashed with the last name
61	     * @param lastName         the owner's last name; hashed with the telephone
62	     * @return the formatted member id
63	     */
64	    public String generate(String region, LocalDate registrationDate, String telephone, String lastName) {
65	        String body = region
66	            + String.format("%02d", FiscalYearResolver.yearOf(registrationDate) % 100)
67	            + Sha256Hex.upperHexPrefix(telephone + lastName, HASH_LENGTH);
68	        return body + LuhnCheckDigit.of(body);
69	    }
70	
71	    /**
72	     * De-duplicate a member id against those already in use. When {@code baseId} does not collide it
73	     * is returned unchanged; otherwise {@code '-<n>'} is appended with the smallest {@code n} of 2 or
74	     * more that yields an id not present in {@code takenIds}.
75	     *
76	     * @param baseId   the member id produced by {@link #generate}
77	     * @param takenIds the member ids already assigned to existing owners
78	     * @return {@code baseId} when unique, otherwise the first available {@code '<baseId>-<n>'}
79	     */
80	    public String deduplicate(String baseId, Collection<String> takenIds) {
81	        Set<String> taken = new HashSet<>(takenIds);
82	        if (!taken.contains(baseId)) {
83	            return baseId;
84	        }
85	        for (int n = 2; ; n++) {
86	            String candidate = baseId + SEPARATOR + n;
87	            if (!taken.contains(candidate)) {
88	                return candidate;
89	            }
90	        }
91	    }
92	
93	    /**
94	     * Extract the region segment from a member id, i.e. everything preceding the fixed trailing
95	     * {@code <FY><HASH8><CHK>} segments. Yields {@link LocalityResolver#UNKNOWN} when the id is
96	     * absent or carries no region segment.
97	     *
98	     * @param memberId a member id produced by {@link #generate}, or {@code null}
99	     * @return the region code embedded in {@code memberId}
100	     */
101	    public static String regionOf(String memberId) {
102	        String body = body(memberId);
103	        if (body == null || body.length() <= TRAILING_LENGTH) {
104	            return LocalityResolver.UNKNOWN;
105	        }
106	        return body.substring(0, body.length() - TRAILING_LENGTH);
107	    }
108	
109	    /**
110	     * Extract the fiscal-year label from a member id, formatted {@code 'FY<YY>'} where {@code YY} is
111	     * the id's {@code FY} segment, e.g. {@code "FY27"}. Returns {@code null} when the id is absent or
112	     * too short to carry a fiscal-year segment.
113	     *
114	     * @param memberId a member id produced by {@link #generate}, or {@code null}
115	     * @return the fiscal-year label embedded in {@code memberId}
116	     */
117	    public static String fiscalYearOf(String memberId) {
118	        String body = body(memberId);
119	        if (body == null || body.length() < TRAILING_LENGTH) {
120	            return null;
121	        }
122	        int fyStart = body.length() - TRAILING_LENGTH;
123	        return "FY" + body.substring(fyStart, fyStart + FISCAL_YEAR_LENGTH);
124	    }
125	
126	    /**
127	     * The member id stripped of any collision suffix, i.e. the {@code <REGION><FY><HASH8><CHK>} body
128	     * that carries the embedded segments. Returns {@code null} when {@code memberId} is {@code null}.
129	     */
130	    private static String body(String memberId) {
131	        if (memberId == null) {
132	            return null;
133	        }
134	        int suffix = memberId.indexOf(SEPARATOR);
135	        return suffix < 0 ? memberId : memberId.substring(0, suffix);
136	    }
137	}
