24	/**
25	 * Emits audit-trail entries for owner lifecycle events to the dedicated {@code AUDIT}
26	 * logger, keeping audit concerns out of the request-handling controller.
27	 */
28	@Component
29	public class OwnerAuditLogger {
30	
31	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
32	
33	    private final OwnerCreatedEventEmitter ownerCreatedEventEmitter;
34	
35	    public OwnerAuditLogger(OwnerCreatedEventEmitter ownerCreatedEventEmitter) {
36	        this.ownerCreatedEventEmitter = ownerCreatedEventEmitter;
37	    }
38	
39	    /**
40	     * Record that an owner was successfully created: a human-readable audit line capturing its id,
41	     * member id, registration date and membership level, plus the immutable structured
42	     * {@link OwnerCreatedEvent}.
43	     *
44	     * @param owner the persisted owner
45	     */
46	    public void ownerCreated(Owner owner) {
47	        AUDIT.info(
48	            "Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
49	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
50	            MembershipLevelCalculator.effectiveMembershipLevel(owner));
51	        ownerCreatedEventEmitter.emit(owner);
52	    }
53	}
