17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Reconciles the structured and flat address inputs of an owner into their canonical stored
24	 * form. Each supplied address field is normalized by {@link AddressNormalizer}, and the flat
25	 * {@code address} is set to the effective address: the composed structured address (the
26	 * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
27	 * appended when present) when a structured {@code addressLine1} is supplied, otherwise the
28	 * normalized flat {@code address}. This keeps the flat {@code address} the single value every
29	 * downstream reader sees, while the structured fields remain available in their normalized form.
30	 */
31	@Component
32	public class AddressResolver {
33	
34	    private final AddressNormalizer addressNormalizer;
35	
36	    public AddressResolver(AddressNormalizer addressNormalizer) {
37	        this.addressNormalizer = addressNormalizer;
38	    }
39	
40	    /**
41	     * Normalizes the address fields of {@code owner} in place and sets its flat {@code address}
42	     * to the effective address, preferring the structured fields when {@code addressLine1} is
43	     * present. A {@code null} owner is left untouched.
44	     */
45	    public void resolve(OwnerFieldsDto owner) {
46	        if (owner == null) {
47	            return;
48	        }
49	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
50	        String line2 = addressNormalizer.normalize(owner.getAddressLine2());
51	        String flat = addressNormalizer.normalize(owner.getAddress());
52	        owner.setAddressLine1(line1);
53	        owner.setAddressLine2(line2);
54	        owner.setAddress(isPresent(line1) ? compose(line1, line2) : flat);
55	    }
56	
57	    /** Compose the normalized structured lines: {@code addressLine1} plus a space and
58	     *  {@code addressLine2} when {@code addressLine2} is present. */
59	    private String compose(String line1, String line2) {
60	        return isPresent(line2) ? line1 + " " + line2 : line1;
61	    }
62	
63	    private boolean isPresent(String value) {
64	        return value != null && !value.isBlank();
65	    }
66	}
