27	public interface OwnerMapper {
28	
29	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
30	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
31	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
32	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
34	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
35	    @Mapping(target = "membershipPoints", expression = "java(computeMembershipPoints(owner))")
36	    @Mapping(target = "membershipLevel", expression = "java(computeMembershipLevel(owner))")
37	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
38	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
41	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
42	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
43	    @Mapping(target = "riskFlag", expression = "java(computeRiskFlag(owner))")
44	    @Mapping(target = "sharesHousehold", ignore = true)
45	    OwnerDto toOwnerDto(Owner owner);
46	
47	    /**
48	     * Builds an owner's canonical self link from its id, formatted
49	     * {@code "/api/owners/<id>"}. Returns {@code null} when the owner has no id yet.
50	     */
51	    default String formatSelfLink(Owner owner) {
52	        if (owner.getId() == null) {
53	            return null;
54	        }
55	        return "/api/owners/" + owner.getId();
56	    }
57	
58	    /**
59	     * Builds an owner's display name from the stored names, formatted as
60	     * {@code "LastName, FirstName"}.
61	     */
62	    default String formatDisplayName(Owner owner) {
63	        return owner.getLastName() + ", " + owner.getFirstName();
64	    }
65	
66	    /**
67	     * Builds an owner's salutation from the stored title and last name: the title
68	     * followed by a single space and the last name when a title is present, or just
69	     * the last name when no title is given.
70	     */
71	    default String formatSalutation(Owner owner) {
72	        String title = owner.getTitle();
73	        if (title == null || title.isBlank()) {
74	            return owner.getLastName();
75	        }
76	        return title + " " + owner.getLastName();
77	    }
78	
79	    /**
80	     * Builds an owner's initials from the stored names as the upper-cased first
81	     * letters of the first and last name, dot-separated with a trailing dot,
82	     * e.g. {@code "J.S."}.
83	     */
84	    default String formatInitials(Owner owner) {
85	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
86	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
87	    }
88	
89	    /**
90	     * Formats an owner's stored E.164 telephone for humans, delegating to
91	     * {@link TelephoneDisplayFormatter}. The raw {@code telephone} stays in E.164 form.
92	     */
93	    default String formatTelephoneDisplay(Owner owner) {
94	        return TelephoneDisplayFormatter.display(owner.getTelephone());
95	    }
96	
97	    /**
98	     * Derives an owner's fiscal year from the {@code FY} segment embedded in its member id,
99	     * formatted {@code 'FY<YY>'}, delegating to {@link MemberIdGenerator}. Returns {@code null}
100	     * when no member id is present.
101	     */
102	    default String formatFiscalYear(Owner owner) {
103	        return MemberIdGenerator.fiscalYearOf(owner.getMemberId());
104	    }
105	
106	    /**
107	     * Computes an owner's membership points from its stored fields, delegating to
108	     * {@link MembershipLevelCalculator}.
109	     */
110	    default int computeMembershipPoints(Owner owner) {
111	        return MembershipLevelCalculator.membershipPoints(owner);
112	    }
113	
114	    /**
115	     * Computes an owner's effective numeric membership level from its stored fields, delegating to
116	     * {@link MembershipLevelCalculator}. Any membership-level cap recorded at creation is applied.
117	     */
118	    default int computeMembershipLevel(Owner owner) {
119	        return MembershipLevelCalculator.effectiveMembershipLevel(owner);
120	    }
121	
122	    /**
123	     * Derives an owner's locality (canonical region) from the region segment embedded in its
124	     * member id, yielding {@code "UNKNOWN"} when the id is absent or carries no region.
125	     */
126	    default String formatLocality(Owner owner) {
127	        return MemberIdGenerator.regionOf(owner.getMemberId());
128	    }
129	
130	    /**
131	     * Derives an owner's timezone as an IANA name from its locality (canonical region),
132	     * delegating to {@link TimezoneResolver}. Returns {@code null} when the region has no
133	     * mapped timezone.
134	     */
135	    default String formatTimezone(Owner owner) {
136	        return TimezoneResolver.timezoneOf(formatLocality(owner));
137	    }
138	
139	    /**
140	     * Derives an owner's preferred contact channel from its stored fields:
141	     * {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}.
142	     */
143	    default String formatContactPreference(Owner owner) {
144	        return owner.hasEmail() ? "EMAIL" : "PHONE";
145	    }
146	
147	    /**
148	     * Derives an owner's identity key from its stored fields, delegating to {@link IdentityKey}.
149	     * This is the same key used to detect duplicate owners on create.
150	     */
151	    default String formatIdentityKey(Owner owner) {
152	        return IdentityKey.of(owner);
153	    }
154	
155	    /**
156	     * Derives an owner's age band from its birth date measured against its registration
157	     * date, delegating to {@link AgeBandResolver}. Returns {@code null} when no birth date
158	     * is present.
159	     */
160	    default String formatAgeBand(Owner owner) {
161	        return AgeBandResolver.bandOf(owner.getBirthDate(), owner.getRegistrationDate());
162	    }
163	
164	    /**
165	     * Derives an owner's marketing segment ({@code '<TIER>_<AREA>'}) from its effective
166	     * membership level and locality, delegating to {@link OwnerSegmentResolver}.
167	     */
168	    default String formatOwnerSegment(Owner owner) {
169	        return OwnerSegmentResolver.segmentOf(computeMembershipLevel(owner), formatLocality(owner));
170	    }
171	
172	    /**
173	     * Derives an owner's risk flag from its stored fields, delegating to {@link OwnerRiskResolver}.
174	     */
175	    default boolean computeRiskFlag(Owner owner) {
176	        return OwnerRiskResolver.isAtRisk(owner);
177	    }
178	
179	    Owner toOwner(OwnerDto ownerDto);
180	
181	    @Mapping(target = "id", ignore = true)
182	    @Mapping(target = "pets", ignore = true)
183	    @Mapping(target = "householdId", ignore = true)
184	    Owner toOwner(OwnerFieldsDto ownerDto);
185	
186	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
187	
188	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
189	
190	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
191	        OwnerPageDto ownerPageDto = new OwnerPageDto();
192	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
193	        ownerPageDto.setPage(ownerPage.getNumber());
194	        ownerPageDto.setSize(ownerPage.getSize());
195	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
196	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
197	        return ownerPageDto;
198	    }
199	}
