19	import java.time.LocalDate;
20	import java.time.Month;
21	
22	/**
23	 * Resolves fiscal-year values for dates. The fiscal year starts on 1 July and is
24	 * identified by the calendar year in which it ends, so 1 July 2026 to 30 June 2027
25	 * is fiscal year 2027. Dates on or after 1 July belong to the next calendar year's
26	 * fiscal year; earlier dates belong to the current calendar year's.
27	 */
28	public abstract class FiscalYearResolver {
29	
30	    /** Month on whose first day each fiscal year begins. */
31	    public static final Month FISCAL_YEAR_START_MONTH = Month.JULY;
32	
33	    /**
34	     * Return the fiscal year the given date falls in, identified by the calendar year in
35	     * which the fiscal year ends: the date's own year for dates before 1 July, or the year
36	     * after for dates on or after 1 July.
37	     */
38	    public static int yearOf(LocalDate date) {
39	        int year = date.getYear();
40	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH.getValue() ? year + 1 : year;
41	    }
42	
43	    /**
44	     * Return the fiscal-year label for the given date, formatted {@code 'FY<YY>'} where
45	     * {@code YY} is the last two digits of the {@link #yearOf(LocalDate) fiscal year},
46	     * e.g. {@code "FY27"}. Returns {@code null} when the date is absent.
47	     */
48	    public static String label(LocalDate date) {
49	        if (date == null) {
50	            return null;
51	        }
52	        return String.format("FY%02d", yearOf(date) % 100);
53	    }
54	
55	    /**
56	     * Return the number of whole fiscal years elapsed between {@code from} and {@code to},
57	     * as the difference of their {@link #yearOf(LocalDate) fiscal years}. Negative when
58	     * {@code to} precedes {@code from}'s fiscal year.
59	     */
60	    public static long elapsedYears(LocalDate from, LocalDate to) {
61	        return (long) yearOf(to) - yearOf(from);
62	    }
63	
64	}
