19	/**
20	 * Computes the standard Luhn check digit (0-9) over the decimal digits contained in a string.
21	 * <p>
22	 * Non-digit characters are ignored, so a value such as {@code "SMI-0007"} is checked over its
23	 * digits {@code "0007"}. Digits are weighted from the rightmost, doubling every second one and
24	 * subtracting 9 from any doubled value above 9; the check digit is what makes the weighted sum
25	 * a multiple of 10.
26	 */
27	public final class LuhnCheckDigit {
28	
29	    private LuhnCheckDigit() {
30	    }
31	
32	    /** @return the Luhn check digit (0-9) over the digits contained in {@code value}. */
33	    public static int of(String value) {
34	        int sum = 0;
35	        boolean doubled = true;
36	        for (int i = value.length() - 1; i >= 0; i--) {
37	            char c = value.charAt(i);
38	            if (c < '0' || c > '9') {
39	                continue;
40	            }
41	            int d = c - '0';
42	            if (doubled) {
43	                d *= 2;
44	                if (d > 9) {
45	                    d -= 9;
46	                }
47	            }
48	            sum += d;
49	            doubled = !doubled;
50	        }
51	        return (10 - (sum % 10)) % 10;
52	    }
53	}
