18	
19	/**
20	 * Computes the American Soundex code of a name: a phonetic index consisting of the (upper-cased)
21	 * first letter followed by three digits, e.g. {@code "Robert" -> "R163"}. Names that sound alike
22	 * share a code, which lets duplicate detection group likely-same surnames that are spelled
23	 * differently. Non-letters are ignored; {@code H} and {@code W} are transparent (they do not break
24	 * a run of same-coded consonants) while vowels do. A value with no letters yields the empty string.
25	 */
26	public final class Soundex {
27	
28	    private Soundex() {
29	    }
30	
31	    /**
32	     * @param value the name to encode (may be {@code null})
33	     * @return the four-character Soundex code, or {@code ""} when {@code value} carries no letters
34	     */
35	    public static String encode(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        StringBuilder letters = new StringBuilder();
40	        for (int i = 0; i < value.length(); i++) {
41	            char c = value.charAt(i);
42	            if (Character.isLetter(c)) {
43	                letters.append(Character.toUpperCase(c));
44	            }
45	        }
46	        if (letters.length() == 0) {
47	            return "";
48	        }
49	        StringBuilder code = new StringBuilder(4).append(letters.charAt(0));
50	        char previous = digit(letters.charAt(0));
51	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
52	            char c = letters.charAt(i);
53	            if (c == 'H' || c == 'W') {
54	                continue;
55	            }
56	            char d = digit(c);
57	            if (d != '0' && d != previous) {
58	                code.append(d);
59	            }
60	            previous = isVowel(c) ? '0' : d;
61	        }
62	        while (code.length() < 4) {
63	            code.append('0');
64	        }
65	        return code.toString();
66	    }
67	
68	    /** @return the Soundex digit for an upper-case letter, {@code '0'} for vowels, H, W and Y. */
69	    private static char digit(char c) {
70	        return switch (c) {
71	            case 'B', 'F', 'P', 'V' -> '1';
72	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
73	            case 'D', 'T' -> '3';
74	            case 'L' -> '4';
75	            case 'M', 'N' -> '5';
76	            case 'R' -> '6';
77	            default -> '0';
78	        };
79	    }
80	
81	    private static boolean isVowel(char c) {
82	        return c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y';
83	    }
84	}
